!function(){"use strict";app.factory("clienteService",(function($injector){let url="Cliente/",mS=$injector.get("mainService"),service={getDataForm:function(query){return mS.getData("get",url+"GetDataForm?json="+JSON.stringify(query),null,!0).then(response=>{if("0"===response.code)throw console.log("Status code 0: Get Data Form Customer"),response;if("1"===response.code){let mainDataRepository=JSON.parse(response.payload);return{tipoIdentificacion:mainDataRepository[0],tipoContribuyentes:mainDataRepository[1],tiempoCreditos:mainDataRepository[2],ciudades:mainDataRepository[3]}}}).catch(response=>{throw response})},getAll:function(query){return mS.getData("get",url+"Get?json="+JSON.stringify(query),null,!0).then(response=>{if("0"==response.code)throw response;if("1"==response.code){let clientes;return(JSON.parse(response.payload)||[]).map(item=>({idCliente:item.idCliente,numeroIdentificacion:item.numeroIdentificacion,nombreFiscal:item.nombreFiscal,direccion:item.direccion,telefono:item.telefono,correo:item.correo,estado:item.estado,consumidorFinal:item.consumidorFinal,totalRecords:item.totalRecords,validationSri:item.validationSri,tipoIdentificacion:item.tipoIdentificacion,esConsumidorFinal:"CF"==item.tipoIdentificacion}))}}).catch(error=>{throw console.log(error),error})},findById:function(id){return clienteRepository.findById(id).catch(errorResponse=>{let error=apiErrorHandler.handle(errorResponse);throw new Error(error.message)})},validateForm:function(data){if(data.numeroIdentificacion)if($("#numeroIdentificacion").hasClass("is-invalid"))tS.toastr("warning","Ingrese el número de Identificación válido");else if("CF"!==data.codigoIdentificacion||13===data.numeroIdentificacion.length)if("C"!==data.codigoIdentificacion||10===data.numeroIdentificacion.length)if("R"!==data.codigoIdentificacion||13===data.numeroIdentificacion.length)if("R"!==data.codigoIdentificacion||"001"===data.numeroIdentificacion.slice(-3))if(data.nombreFiscal)if(data.nombreComercial)if(data.correos.length>0&&!data.correos.every(item=>validationsUtils.isEmail(item)))tS.toastr("warning","Verifique que los correos  esten ingresado correctamente");else{if(data.idTiempoCredito)return data.direccion=data.direccion?validationsUtils.letterInline(data.direccion):"",data.telefono=data.telefonos.length>0?data.telefonos.join(";"):"",data.correo=data.correos.length>0?data.correos.join(";"):"",data.placa=data.placas.length>0?data.placas.join(";"):"",!0;tS.toastr("warning","Seleccione el Tiempo Credito")}else tS.toastr("warning","Ingrese el nombre Comercial");else tS.toastr("warning","Ingrese el nombre Fiscal");else tS.toastr("warning","Número de RUC tiene que contener 001");else tS.toastr("warning","Número de RUC tiene que ser de 13 dígitos");else tS.toastr("warning","Número de Cédula tiene que ser de 10 dígitos");else tS.toastr("warning","Número de Consumidor Final tiene que ser de 13 dígitos");else tS.toastr("warning","Ingrese Número de Identificación")},save:function(data){return clienteRepository.save(data).catch(errorResponse=>{let error=apiErrorHandler.handle(errorResponse);throw new Error(error.message)})},update:function(id,data){return clienteRepository.update(id,data).catch(errorResponse=>{let error=apiErrorHandler.handle(errorResponse);throw new Error(error.message)})},checkClientByIdentification:function(query,codigoIdentificacion,callback){clienteRepository.checkClientByIdentification(query).then(response=>{"0"==response.code&&callback(codigoIdentificacion),"1"==response.code&&Swal.fire({title:"Cliente Registrado",html:`\n                                <small><strong>Nro. Identificación</strong></small>\n                                <br>\n                                <p class="text-muted small">${response.numeroIdentificacion}</p>\n                                <small><strong>Nombre Fiscal</strong></small> <br>\n                                <p class="text-muted small">${response.nombreFiscal}</p>\n    \n                                <small><strong>Nombre Comercial</strong></small> <br>\n                                <p class="text-muted small">${response.nombreComercial}</p>\n                            `,icon:"info",showCloseButton:!0,showCancelButton:!0,focusConfirm:!0,confirmButtonText:'<i class="fa fa-thumbs-up"></i> Validar datos!',confirmButtonAriaLabel:"Validar datos!",cancelButtonText:'<i class="fa fa-thumbs-down"></i> Cancelar',cancelButtonAriaLabel:"Cancelar"}).then(result=>{result.isConfirmed&&callback(codigoIdentificacion)})}).catch(errorResponse=>{let error=apiErrorHandler.handle(errorResponse);throw new Error(error.message)})},checkClientSRIByCedula:function(identificacion){return clienteRepository.checkClientSRIByCedula(identificacion)},checkClientSRIByRUC:function(identificacion){return clienteRepository.checkClientSRIByRUC(identificacion)},onKeyupEmail:function(item){let textChip=item.target.value||"";textChip=validationsUtils.removeAccents(textChip),item.target.value=textChip.toLowerCase()},transformChipEmail:function(item){let textChip=item||"";textChip=validationsUtils.removeAccents(textChip),item=textChip.toLowerCase()}};return service}))}(window.angular);